export const knowledge = [
 {id:'resume-evidence',title:'Make experience specific',publisher:'Harvard Mignone Center for Career Success',url:'https://careerservices.fas.harvard.edu/resources/create-a-strong-resume/',text:'Resume experience should connect relevant actions with specific evidence. Use clear action verbs and factual examples. Include outcomes or scope when you can substantiate them. Tailor the resume to the opportunity. Never invent numbers or achievements.'},
 {id:'resume-ai',title:'Use AI as a revision partner',publisher:'Harvard Mignone Center for Career Success',url:'https://careerservices.fas.harvard.edu/ai-resumes-and-cover-letters/',text:'AI can help identify experiences relevant to a job description and suggest language for resumes and cover letters. Review suggestions and keep your own truthful experience and voice.'},
 {id:'interview-practice',title:'Prepare for an interview',publisher:'CareerOneStop',url:'https://cloudfront.careeronestop.org/JobSearch/Interview/get-ready.aspx?frd=true',text:'Prepare for interviews by practicing common questions on paper and out loud. Think through examples of your experience and skills. Keep explanations constructive when discussing difficult experiences.'},
 {id:'behavioral',title:'Behavioral interview examples',publisher:'CareerOneStop',url:'https://cloudfront.careeronestop.org/Veterans/JobSearch/Interviews/common-interview-questions.aspx',text:'Behavioral questions ask about specific past situations, including reaching goals and resolving conflict. Prepare concrete examples of what you did and how you approached the situation.'},
 {id:'student-projects',title:'Turn coursework into evidence',publisher:'Career Compass coaching framework',url:null,text:'Student projects, volunteer work and campus leadership can supply examples when professional experience is limited. Describe the problem, your contribution, tools used and an outcome you can verify. Label academic work as academic work.'},
 {id:'skill-gap',title:'Check a skill gap before studying',publisher:'Career Compass coaching framework',url:null,text:'A skill missing from a resume is missing evidence, not proof that you lack the skill. Review the actual job requirement, decide whether you have experience, and add an accurate example. Otherwise build a small project to practice the skill.'},
 {id:'plan',title:'Make a small learning plan',publisher:'Career Compass coaching framework',url:null,text:'Prioritize one skill mentioned in the target job. Define a small portfolio project, set weekly milestones and document the result. The suggested four-week plan is an editable coaching template, not a guarantee of job readiness.'}
];
const stop=new Set('the a an to of and in for with on is are be or as by from this that you your our we will have at it not can'.split(' '));
export function tokenize(s){return String(s).toLowerCase().match(/[a-z0-9+#]+/g)?.filter(x=>!stop.has(x))||[]}
export function retrieve(query,docs=knowledge,limit=3){
 const terms=[...new Set(tokenize(query))]; const tokenDocs=docs.map(d=>tokenize(d.title+' '+d.text)); const avg=tokenDocs.reduce((s,d)=>s+d.length,0)/(docs.length||1);
 return docs.map((d,i)=>{const tokens=tokenDocs[i];let score=0; for(const term of terms){const tf=tokens.filter(t=>t===term).length;if(!tf)continue;const df=tokenDocs.filter(t=>t.includes(term)).length;const idf=Math.log(1+(docs.length-df+0.5)/(df+0.5));score+=idf*tf*2.2/(tf+1.2*(0.25+0.75*tokens.length/(avg||1)))}return {...d,score}}).filter(d=>d.score>0).sort((a,b)=>b.score-a.score).slice(0,limit)
}
const catalog={
 'SQL':['sql','mysql','postgresql','sqlite'], 'Python':['python','pandas','numpy'], 'Excel':['excel','spreadsheets','vlookup','pivot tables'], 'Tableau':['tableau'], 'Power BI':['power bi','powerbi'], 'Data analysis':['data analysis','data analytics','analyzing data'], 'Data visualization':['data visualization','visualisation','visualization','dashboards'], 'Statistics':['statistics','statistical'], 'Machine learning':['machine learning','scikit-learn'], 'Communication':['communication','presentations','presented','communicate'], 'Teamwork':['teamwork','collaborated','collaboration','team player'], 'Leadership':['leadership','led a team','team lead'], 'Project management':['project management','project planning'], 'Agile':['agile','scrum'], 'Requirements gathering':['requirements gathering','business requirements','requirements analysis'], 'JavaScript':['javascript','typescript'], 'React':['react','reactjs'], 'HTML':['html'], 'CSS':['css'], 'Java':['java'], 'Git':['git','github','version control'], 'AWS':['aws','amazon web services'], 'APIs':['api','apis','rest api'], 'Marketing':['marketing'], 'Customer research':['customer research','user research'], 'Finance':['finance','financial analysis'], 'Accounting':['accounting'], 'Writing':['writing','copywriting','written'], 'Sales':['sales'], 'Design':['figma','ux','ui design'], 'RAG':['rag','retrieval augmented','retrieval-augmented'], 'AI':['ai','artificial intelligence','generative ai'], 'Docker':['docker'], 'Kubernetes':['kubernetes'], 'C++':['c++'], 'C#':['c#']
};
function escapeRegex(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}
export function hasTerm(text,term){return new RegExp('(?:^|[^a-z0-9+#])'+escapeRegex(term)+'(?=$|[^a-z0-9+#])','i').test(text)}
function evidence(text,aliases){return text.split(/\n|(?<=[.!?])\s+/).find(line=>aliases.some(a=>hasTerm(line,a)))?.trim().slice(0,400)||''}
export function analyze(resume,job,role,docs=knowledge){
 if(resume.trim().length<40||job.trim().length<40)throw new Error('Add at least 40 characters to both your resume and job description so there is enough context to compare.');
 const rows=Object.entries(catalog).filter(([,aliases])=>aliases.some(a=>hasTerm(job,a))).map(([skill,aliases])=>({skill,found:aliases.some(a=>hasTerm(resume,a)),resumeEvidence:evidence(resume,aliases),jobEvidence:evidence(job,aliases)}));
 const found=rows.filter(r=>r.found), gaps=rows.filter(r=>!r.found);
 const sources=retrieve('resume experience evidence skill gap '+gaps.map(g=>g.skill).join(' '),docs);
 return {role:role.trim()||'Your target role',rows,found,gaps,sources,coverage:rows.length?Math.round(found.length/rows.length*100):null,notes:[
 'This comparison uses a fixed skill dictionary and phrase matching. It does not assess proficiency or hiring probability.',
 'A phrase match can occur in coursework, a skills list, a negated sentence, or an unrelated context. Review each excerpt.',
 'Requirements outside the dictionary, years of experience, degrees and required versus preferred qualifications are not evaluated.'
 ],trace:[{tool:'Read inputs',detail:`Compared ${resume.length} resume characters with ${job.length} job-description characters.`},{tool:'Compare skill mentions',detail:`Found ${rows.length} dictionary skills in the job description; ${found.length} also appear in the resume.`},{tool:'Retrieve guidance',detail:`BM25 ranked ${docs.length} guidance passages and returned ${sources.length} sources.`},{tool:'Build practice plan',detail:'Created an editable four-week template from the missing mentions. No model was called.'}]};
}
export function makePlan(result){const focus=result.gaps.slice(0,2).map(g=>g.skill).join(' and ')||'your strongest relevant project'; return [
 {week:'Week 01',title:'Strengthen your story',text:'Review the comparison. Add truthful evidence for skills you already have; improve two resume bullets using an action, context and a verified outcome.'},
 {week:'Week 02',title:'Build one proof point',text:`Choose a small project involving ${focus}. Define its question, scope, and a deliverable you can finish in a week.`},
 {week:'Week 03',title:'Make your work visible',text:'Finish the project and write a short case study covering the problem, your contribution, methods, limitations and results.'},
 {week:'Week 04',title:'Practice and apply',text:`Practice three interview answers for ${result.role}. Tailor one application and ask a classmate or career advisor for feedback.`}
 ]}
export function questions(result){const skill=result?.gaps?.[0]?.skill||result?.found?.[0]?.skill||'a skill relevant to the role'; return [
 `Tell me about a project that prepares you for ${result?.role||'your target role'}. What was your contribution?`,
 'Describe a time your team disagreed. What did you do, and what happened?',
 `How would you approach a small project using ${skill}? Be clear about what you already know and what you would need to learn.`,
 'Tell me about a difficult problem. How did you evaluate your options and measure the result?',
 'What would you like to ask the interviewer about the team and the role?'
 ]}
export function interviewFeedback(answer){const n=answer.trim().split(/\s+/).filter(Boolean).length;return {words:n,items:[{label:'Context',tip:'Name a specific situation and the goal.',signal:/project|during|when|team|class|internship/i.test(answer)},{label:'Your actions',tip:'Explain what you personally did and why.',signal:/\bi\b.{0,30}(built|analy|created|led|organized|decided|tested|designed|wrote|developed|resolved)/i.test(answer)},{label:'Outcome',tip:'Describe a result or lesson you can verify.',signal:/result|learned|improved|reduced|increased|completed|delivered|\d/i.test(answer)}],note:'This is a keyword-based self-review checklist. Detected words do not establish answer quality or technical correctness.'}}
export const sampleResume='Jordan Lee\nMS Management Information Systems\nSKILLS\nSQL, Excel, Tableau, Python\nPROJECTS\nAnalyzed campus dining data with SQL and built a Tableau dashboard for a class project.\nCollaborated with three classmates to present recommendations to the course instructor.\nEXPERIENCE\nStudent assistant: maintained Excel spreadsheets tracking event registrations.\nPresented a project summary to a student organization.';
export const sampleJob='Business Analyst Intern\nWe are looking for a student with SQL, Excel, and data analysis skills.\nResponsibilities include gathering business requirements, building dashboards in Power BI, and delivering presentations to stakeholders.\nExperience with Python and Agile is preferred. Strong communication and collaboration are valued.\nAcademic projects are welcome.';
